from math import sqrt

def is_rotatable_number(num, base):
    str_num = str(num)
    while len(str_num) < len(num):
        str_num = '0' + str_num
    if len(str_num) != len(num):
        return 0
    for i in range(1, len(str_num)):
        if int(str_num[i:]) * base != int(str_num[:len(str_num)-i]) * 10 ** (i-1):
            return 0
    return 1

def find_largest_base(n, x):
    # Find the largest prime factor of x that is less than n
    largest_prime_factor = -1
    for i in range(2, int(sqrt(x)) + 1):
        if x % i == 0:
            largest_prime_factor = i
            while x % i == 0:
                x //= i
    if x > 1:
        largest_prime_factor = x
    # If no prime factor found, x might be a prime number
    if largest_prime_factor == -1 and int(sqrt(x))**2 == x:
        smallest_prime_factor = 2
        while smallest_prime_factor < n:
            if x % smallest_prime_factor:
                return x // smallest_prime_factor
            else:
                largest_prime_factor = smallest_prime_factor
                smallest_prime_factor += 1
    # Check if the largest prime factor is a valid base
    if is_rotatable_number(largest_prime_factor, largest_prime_factor):
        return largest_prime_factor
    else:
        return -1

