from collections import defaultdict

def mod_pow(x, n, p):
    result = 1
    base = x % p
    while n > 0:
        if n & 1:
            result = (result * base) % p
        n >>= 1
        base = (base * base) % p
    return result

def calculate_k(k, n, graph):
    cache = defaultdict(int)
    for i in range(1 << n):
        subset = set()
        for j in range(n):
            if (i >> j) & 1:
                subset.add(j)
        subset = list(subset)
        total = 1
        cache[i] = total
        for j in range(k-1):
            next_total = 0
            for node in subset:
                for neighbor in graph[node]:
                    if neighbor in subset:
                        next_total += cache[i & ~(1 << node)]
            total = (total + next_total) % 1000000007
            cache[i] = total
    return cache[1 << n - 1]

