import math

def is_rotatable_number(num_str, base):
    """Check if the number formed by the rotations of num_str under base equals num_str itself."""
    length = len(num_str)
    for i in range(1, 7):
        rotated = ""
        for j in range(length - 1, -1, -1):
            rotated += num_str[j]
        if rotated == num_str:
            return True
    return False

