from typing import List

def min_coins_to_win(a: str, b: str) -> int:
    """
    Calculates the minimum number of coin operations required to transform
    'a' into 'b' and prints the sequence of moves to achieve this
    """
    if len(a) != len(b):
        return -1

    ni = len(a)
    i = 0

    while i < ni and a[i] == b[i]:
        i += 1

    if i == ni:
        return 0

    # Count the number of changes needed
    c_change = 0
    s_change = 0
    s11 = []
    s20 = []

    for j in range(i):
        if abs(int(a[i + j]) - int(b[i + j])) > 1:
            return -1
        if int(b[i + j]) - int(a[i + j]) < 0:
            s_change += 1
        if int(b[i + j]) - int(a[i + j]) > 0:
            s_change += 1
        c_change += 1

        if b[i + j] == '0':
            s20.append((i + j, -1))
        elif b[i + j] == '9':
            s11.append((i + j, 1))

    if s20 and s11:
        return -1
    i -= c_change

    # Count places to change
    if c_change & 1:
        if s_change > 0:
            s_change -= 1
        else:
            return -1
    s_change = abs(s_change - c_change // 2)
    # Count how many will change on even places
    swap_ = {} 
    for nn, jn in s20:
        if nn in swap_:
            swap_[nn].append(jn)
        else:
            swap_[nn] = [jn]
    for nn, jn in s11:
        if nn in swap_:
            swap_[nn].append(-jn)
        else:
            swap_[nn] = [-jn]

    moves = []
    ks = [c_change]
    k = c_change

    while k:
        i -= k
        while i >= 0 and ks[0] not in swap_:
            i -= 1
            ks[0] -= 1
        while i >= 0 and ks[0] in swap_:
            ks[0] -= 1
            i_seq = i
            i -= 1
            while i_seq >= 0:
                rn = -swap_[ks[0]][i_seq]
                if rn * i_seq > 0 or rn >= 0:
                    i_seq -= 1
                    if rn >= 0:
                        moves.append((rn + 1, jn - 1))
                    else:
                        moves.append((-rn - 1, jn + 1))
                else:
                    i_seq -= 1
                    i -= 1
    return len(moves)

