    result = [0] * (n + 1)
    for i in range(n):
        result[i] = factorial(-i - 1) % MOD
    return result

def binomial_coefficient(n, k, mod=MOD):
    return factorial(n) * inverse_factorial(n - k)[k] % mod

def count_ways_to_pick_elements(n, m):
    if m & 1:
        return 0
    ks = [0] * (n - 1)
    Rs = 1
    for i in range(1, int(sqrt(m)) + 2):
        if m % i == 0:
            R = m // i
            S = 1
            for j in range(1, R + 1):
                k = i * j - 1
                k = min(k, n - 1)
                k = max(k, 0)
                Rs *= binomial_coefficient(k, j) % MOD
                if k > 0:
                    Rs *= binomial_coefficient(n - 1 - k, j - 1) % MOD
            Rs %= MOD
            Rs = (2 * Rs) % MOD
            available_kinds = 0
            for k in range(1, j + 1):
                available_kinds += binomial_coefficient(k, R) % MOD
            available_kinds = sqrt(available_kinds) % MOD
            available_kinds = inverse_factorial(n - 2 * R - 1)[available_kinds] % MOD

            for a in ks:
                if i == R and a >= k * j:
                    available_kinds -= 1
            Rs = (Rs ** (min(available_kinds, k // j + 1))) % MOD
    else:
        Rs = 1
        for i in range(1, m // 2):
            Rs *= binomial_coefficient(i - 1, i) % MOD
            Rs = Rs ** 2 % MOD
    return Rs

