def is_adjacent(s1, s2):
    return min(ord(s1), ord(s2)) <= max(ord(s1), ord(s2)) + 1

def perform_operation(s, i):
    if i == len(s) - 1:
        return s
    s1, s2 = s[i], s[i + 1]
    if is_adjacent(s1, s2):
        s_new = s[:i + 1] + s2 + s[i + 2:]
    else:
        s_new = s[:i] + s2 + s[i + 1:i + 2] + s2 + s[i + 2:]
    return perform_operation(s_new, i + 1)

def find_smallest_string(n, s):
    visited = set()
    result = []
    for i in range(n - 1):
        if (i, i + 1) not in visited:
            visited.add((i, i + 1))
            s_new = perform_operation(s, i)
            result.append(s_new)
    return min(result)

