def find_shortest_path_and_total_length(k, scores):
    if k in scores:
        return (0, scores[k] + 1)

    max_score = -1
    node = None

    for node in range(1, k + 1):
        path_length = 0

        if node < k - 1 and k % node == 0:
            num = k // node
            prime_divisors = deque([num])
            while True:
                divisor = prime_divisors.popleft()
                if divisor == 1:
                    break
                factors = []
                while True:
                    if node % divisor == 0:
                        node //= divisor
                        factors.append(divisor)
                    if divisor * divisor > node:
                        break
                prime_divisors.extend(factors)
                if num % k == 0 and len(prime_divisors) <= k - 1:
                    path_length += 1

            if node > k - 1 and len(prime_divisors) <= k - 1:
                path_length += 1

        scores[node] = path_length
        max_score = max(max_score, path_length + 1)

    return (max_score, max_score + 1)

