Here's how you can do it:

```python
def min_coins_to_win(n, a, b):
    # Initialize the DP table
    dp = [[float('inf')] * (10**n) for _ in range(n + 1)]
    dp[0][0] = 0

    for i in range(1, n + 1):
        for j in range(10**i):
            for k in range(10):
                # Calculate possible transformations
                for l in range(2):
                    temp = str(j) + str(i)
                    if temp == str(k):
                        dp[i][j] = min(dp[i][j - 1], dp[i - 1][k] + 1)
                        continue

                    # Reverse operation if the number of changes is even
                    if (j - 1) % 2 == 0:
                        temp = str(k) + str(10**i - 1)
                        temp = temp[::-1]
                        if temp == str(j):
                            dp[i][j] = min(dp[i][j - 1], dp[i - 1][k - 10] + 1)

                    # Normal operation if the number of changes is odd
                    temp = str(k) + str(10**i - 1)
                    temp = temp[::-1]
                    if temp == str(j - 1):
                        dp[i][j] = min(dp[i][j - 1], dp[i - 1][k - 10] + 1)

    # Return the minimum coins needed and the optimal moves
    if dp[n][-1] == float('inf'):
        return -1, []
    else:
        moves = []
        k = n - 1

        while k >= 0:
            if dp[k][-1] == float('inf'):
                k -= 1
            else:
                inverse = True
                min_k = k
                while min_k > 0:
                    x = dp[k - 1][:min_k + 1]
                    if str(k) + str(10**k - 1) == str(x):
                        inverse = False
                        break
                    min_k -= 1

                if x == []:
                    x = [1, 1]
                elif x == [10**k - 1]:
                    x = [1, -1]
                elif len(x) == 2:
                    x = [10**k - 1, -10**k + 1]

                if inverse:
                    moves.append(f"{x[0]} {x[1]}\n")

                k -= 1

        return dp[n][-1], [*moves]
